import { RouterContext, createRouterState, isMounted } from "./routing.js";

// The provider: the package's own component supplies the context value, as
// @solidjs/router's `createRouter` component does in `routers/factory.jsx`.
export function Router(props) {
  if (isMounted()) throw new Error("already mounted");
  const state = createRouterState();
  return <RouterContext value={state}>{props.children}</RouterContext>;
}

// A second visible provider must be proven too; provider cardinality alone
// cannot reject the selected-package getter path under ADR 0300.
export function OtherRouter(props) {
  const state = createRouterState();
  return <RouterContext value={state}>{props.children}</RouterContext>;
}
